// New returns an Opentofu module whose tofu binary comes from
// <registry>/opentofu/opentofu:<version>-minimal, placed onto base.
func (r *Query) Opentofu(opts ...OpentofuOpts) *Opentofu { // opentofu (../../../../../daggerverse/opentofu/main.go:59:1)
	q := r.query.Select("opentofu")
	for i := len(opts) - 1; i >= 0; i-- {
		// `registry` optional argument
		if !querybuilder.IsZeroValue(opts[i].Registry) {
			q = q.Arg("registry", opts[i].Registry)
		}
		// `version` optional argument
		if !querybuilder.IsZeroValue(opts[i].Version) {
			q = q.Arg("version", opts[i].Version)
		}
		// `base` optional argument
		if !querybuilder.IsZeroValue(opts[i].Base) {
			q = q.Arg("base", opts[i].Base)
		}
	}

	return &Opentofu{
		query: q,
	}
}
